/* From Uiverse.io by Fareny  - Tags: simple, purple, loader, like, circle, html, css */
.__UIV_SCOPE__ .loader {
  display: flex;
  align-items: center;
  justify-content: center;
  background: #141218;
}

.__UIV_SCOPE__ .iconLoaderProgress {
  display: flex;
  align-items: center;
  justify-content: center;
  animation-duration: 2s;
  animation-timing-function: linear;
  animation-iteration-count: infinite;
  animation-name: rotateLoader;
}

.__UIV_SCOPE__ .iconLoaderProgress svg {
  stroke-width: 16px;
  fill: none;
  transform-origin: center;
  z-index: 999;
}

.__UIV_SCOPE__ .iconLoaderProgressFirst circle,
.__UIV_SCOPE__ .iconLoaderProgressSecond circle,
.__UIV_SCOPE__ .iconLoaderProgressFirst,
.__UIV_SCOPE__ .iconLoaderProgressSecond {
  animation-timing-function: ease-in-out;
  animation-iteration-count: infinite;
}

.__UIV_SCOPE__ .iconLoaderProgressFirst circle,
.__UIV_SCOPE__ .iconLoaderProgressSecond circle {
  animation-duration: 3s;
  border-radius: 15px;
}

.__UIV_SCOPE__ .iconLoaderProgressFirst,
.__UIV_SCOPE__ .iconLoaderProgressSecond {
  position: absolute;
  animation-duration: 6s;
}

.__UIV_SCOPE__ .iconLoaderProgressFirst circle {
  animation-name: circleFirst;
  stroke-dasharray: 628, 628;
  stroke-dashoffset: 0;
  stroke: #7c57f4;
  stroke-linecap: round;
}

.__UIV_SCOPE__ .iconLoaderProgressSecond {
  transform: rotate(-14deg);
}

.__UIV_SCOPE__ .iconLoaderProgressSecond circle {
  animation-name: circleSecond;
  stroke-dasharray: 628, 628;
  stroke-dashoffset: 0;
  stroke: #bfb2f7;
  stroke-linecap: round;
}

@keyframes circleFirst {
  from,
  to {
    stroke-dashoffset: 50;
  }

  50% {
    stroke-dashoffset: 625;
  }
}

@keyframes circleSecond {
  from,
  to {
    stroke-dashoffset: -625;
  }

  50% {
    stroke-dashoffset: -50;
  }
}

@keyframes rotateLoader {
  from {
    transform: rotate(0deg);
  }

  to {
    transform: rotate(360deg);
  }
}
